use serde_json::Value;

pub fn solve(input: Value) -> Value {
    if let Value::String(s) = input {
        let mut num = 0;
        let mut sign = 1;
        let mut i = 0;

        while i < s.len() && s[i] == '-' {
            sign = -1;
            i += 1;
        }

        let mut j = i;
        while j < s.len() && s[j] >= '0' && s[j] <= '9' {
            num = num * 10 + (s[j] - '0');
            j += 1;
        }

        if j == i {
            return Value::Null;
        }

        if s[i] == '.' {
            i += 1;
            let mut k = i;
            while k < s.len() && s[k] >= '0' && s[k] <= '9' {
                num = num * 10 + (s[k] - '0');
                k += 1;
            }

            if k == i {
                return Value::Null;
            }

            if j == i {
                return Value::Null;
            }

            if s[i] != '0' {
                return Value::Null;
            }

            i = k;
        }

        if j == i {
            return Value::Null;
        }

        if s[i] != '0' {
            return Value::Null;
        }

        if num < -1000000 || num > 1000000 {
            return Value::Null;
        }

        Value::Number(serde_json::Number::from(num) * sign as f64)
    } else {
        Value::Null
    }
}
